const existing = $('customer found?').item.json.fields['Order History'] || '';

// Duplicate order_ids occur during development or testing i.e.
// same data is sent through the webhook. This 'duplicate' prevents
// database pollution.
const duplicate = existing.split(",").includes($('paid or unpaid?').item.json.body.order_id) 

const newHistory = existing ? `${existing}${duplicate ? "" :  ', ' + $('paid or unpaid?').item.json.body.order_id}` : $('paid or unpaid?').item.json.body.order_id;

const newLTV = (Number($('customer found?').item.json.fields['Lifetime Value']) || 0) + (duplicate ? 0 : Number($('paid or unpaid?').item.json.body.order_total));

return { json: { record_id: $('customer found?').item.json.id, order_history: newHistory, ltv: newLTV } };

const items = $input.all();
const statuses = items.map(i => i.json.fulfillment_status || i.json.crm_status || i.json.ledger_status);

const orderId = $('paid or unpaid?').item.json.body.order_id;
const hasFailure = statuses.some(s => s.startsWith('❌'));

return [{
  json: {
    message: `${hasFailure ? '⚠️' : '✅'} Order ${orderId} — ${statuses.join(', ')}${hasFailure ? '\nSee automation error log for details.' : ''}`
  }
}];
